type Breaker struct {
    failures  int
    threshold int
    open      bool
}

func (b *Breaker) Call(fn func() error) error {
    if b.open {
        return errCircuitOpen
    }
    if err := fn(); err != nil {
        b.failures++
        if b.failures >= b.threshold {
            b.open = true
        }
        return err
    }
    return nil
}

